KEYS=sorted(LEX,key=len,reverse=True)
def ruby(s):
 out=[];i=0
 while i<len(s):
  k=next((k for k in KEYS if s.startswith(k,i)),None)
  if k:
   token={'text':k}
   if re.search('[一-龯々]',k):token['reading']=LEX[k]
   out.append(token);i+=len(k)
  else:
   if re.search('[一-龯々]',s[i]):raise ValueError('Missing reading: '+s[i:i+20])
   if out and 'reading' not in out[-1]:out[-1]['text']+=s[i]
   else:out.append({'text':s[i]})
   i+=1
 return out

